-- Rifts World Book 22: Free Quebec - its bestiary and its notable NPCs.
-- 0 creatures (migration 074) and 12 notable NPCs (migration 072),
-- with their attacks in stat_attacks (migration 073).
--
-- One-off data script, run once per environment. NOT a migration.
--
--   node scripts/d1-apply.mjs --local apps/character-creator/db/~105-free-quebec-old-bones-npcs.sql
--
-- Written by scripts/bestiary-sql.mjs from 1 worker file(s). Every
-- creature row passes creatureFormulaGaps, every value is printable ASCII,
-- and an 8-word shingle check of the prose fields against the book's cached text finds no copied run.

INSERT INTO notable_npcs (slug, name, real_name, title, system, race, occ, level, alignment, age, height, weight, attributes, hp, sdc, mdc, ppe, isp, ar, horror_factor, combat, bonuses_note, skills, skills_note, natural_abilities, magic, psionics, super_powers, cybernetics, weapons_and_equipment, money, disposition, allies, enemies, description, source_book) VALUES
('pierre-champlain', 'Pierre Champlain', NULL, 'Celebrity gambler of Old Bones', 'rifts', NULL, '10th level Gambler and Lady''s Man (playboy)', 10, 'Anarchist', '44 (looks 30)', NULL, NULL, '{"IQ":17,"ME":12,"MA":22,"PS":14,"PP":18,"PE":10,"PB":19,"Spd":11}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Thieving, seduction, cardsharp, streetwise and intelligence skills; Hand to Hand: Expert; marksman with energy pistols and Vibro-Knives', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Well schooled, self-assured and courteous, at ease with rich and poor alike. Prefers to stay out of fights and duels, and keeps to himself between showy public outings.', NULL, NULL, 'A famous gambler with a Riverside mansion, received by everyone from politicians to crooks. Street talk makes him either a Quebec intelligence plant or a Black Market boss; the book settles neither. Once briefly involved with Sylvette Jiroyan. Light brown hair, blue eyes.', 'Rifts World Book 22: Free Quebec p.157'),
('sylvette-jiroyan', 'Sylvette Jiroyan', NULL, 'Arms dealer; owner of Sylvette''s weapons shop, Trade Center, Old Bones', 'rifts', NULL, '10th level Assassin', 10, 'Miscreant', '40 (looks 28)', NULL, NULL, '{"IQ":20,"MA":23,"PS":21,"PP":22,"PB":20,"Spd":15}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Bionic left arm (looks and feels human): two retractable finger blades, finger camera, fingerjack (pinky), retractable wrist needle for drugs and poisons; Toxic gas lung filter; Universal ear implant; Amplified hearing; Sound filtration system; Clock calendar', NULL, NULL, 'Alluring and secretive. Seldom takes contracts in person any more, favouring commerce and political scheming, and sends out a few chosen killers and spies, most of them women.', 'The Black Market; spies, smugglers and turncoats inside the CS and Free Quebec who supply her stock; Pierre Champlain (former lover, possibly a business partner)', NULL, 'Has sold arms in Old Bones for 12 years and is said to be able to obtain any weapon or armor for a high enough price, though only on request. A former Black Market killer; she has six or more tattoos but is no True Atlantean. Attributes not listed are average.', 'Rifts World Book 22: Free Quebec p.158, 160'),
('roland-desjardin', 'Roland Desjardin', NULL, 'Black Marketeer; Ye Old Tobacco Shop, Trade Center, Old Bones', 'rifts', NULL, NULL, NULL, 'Aberrant', NULL, NULL, NULL, '{"IQ":19,"ME":14}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'A well-known Black Market fixer who works behind a tobacconist''s. For vouched-for clients with money he and his men set up crimes, killings and hard-to-find goods through go-betweens, and supply forged papers and identities. Attributes not listed are average.', 'Rifts World Book 22: Free Quebec p.160'),
('cyrean-hoist', 'Cyrean Hoist', NULL, 'Owner of The Foundation House, Trade Center, Old Bones', 'rifts', 'Human', '12th level Operator', 12, 'Unprincipled', '56', NULL, NULL, '{"IQ":17,"PP":21,"PB":18}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'The Terminal Headkick Foundation (former adventuring companions, who still visit)', NULL, 'A rich veteran Operator who earned his money adventuring with the Terminal Headkick Foundation and now keeps a 64-room lodge for Operators only. Rumors tie him to the Black Market, the CS or Naruni; locals credit none of them. Attributes not listed are average.', 'Rifts World Book 22: Free Quebec p.160'),
('shelly-winslow', 'Shelly Winslow', NULL, 'Office manager, Salmand Special Investigations, Old Bones', 'rifts', NULL, '4th level Psi-Nullifier', 4, 'Principled', NULL, NULL, NULL, '{"IQ":14,"ME":17,"MA":12,"PP":15,"PB":24}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Salmand (employer and former boyfriend); Philip Dushane; Martin Petit', NULL, 'Brunette receptionist, clerk and all-round assistant at the agency, still fond of Salmand, whom she used to date. Her psychic gift is kept quiet and she lends it to him on unusual cases. The class is in Rifts Psyscape p.66. Attributes not listed are average.', 'Rifts World Book 22: Free Quebec p.160'),
('martin-petit', 'Martin Petit', NULL, 'Researcher and office assistant, Salmand Special Investigations, Old Bones', 'rifts', NULL, '8th level Rogue Scholar', 8, 'Scrupulous', NULL, NULL, NULL, '{"IQ":20,"MA":18,"PS":8,"PP":7,"Spd":14}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Always upbeat, believes well of everybody and trusts too easily; years at the agency have taught him no street sense.', 'Salmand; Philip Dushane; Shelly Winslow', NULL, 'Does the agency''s research and keeps its computer and large, well-protected databases. He would like to be a detective but is too gentle for field work in this city, which makes him the way to reach Salmand. Attributes not listed are average.', 'Rifts World Book 22: Free Quebec p.160-161'),
('philip-dushane', 'Philip Dushane', NULL, 'Private investigator, Salmand Special Investigations, Old Bones', 'rifts', NULL, 'Ex-8th level NTSET Protector (Chi-Town)', 8, 'Scrupulous', NULL, NULL, NULL, '{"IQ":12,"ME":17,"PS":20,"PP":15,"Spd":23}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Blunt, tough and short on tact, though a fine investigator. Salmand is his closest friend and the trust runs both ways.', 'Salmand; many street informants among the poor of Old Bones', NULL, 'A former Chi-Town NTSET man who specialises in monsters and the supernatural. He quit the Coalition out of disgust with its politics and dishonesty and drifted as an adventurer before joining Salmand. He keeps contacts at home but is not the CS spy rumor makes him. The class is in Coalition War Campaign p.188. Attributes not listed are average.', 'Rifts World Book 22: Free Quebec p.161'),
('salmand', 'Salmand', NULL, 'Head of Salmand Special Investigations, Old Bones', 'rifts', 'True Atlantean', '7th level True Atlantean Nomad', 7, 'Scrupulous', '98 (appears early thirties)', '6 ft, 6 in (1.95 m)', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Magic tattoos (none named)', NULL, NULL, NULL, 'Light body armor worn under a cloak', NULL, 'Picks his own cases, bills the rich heavily and works for little or nothing for the needy. Dogged once he starts. Stays out of public view so the tattoos can be used unseen.', 'Philip Dushane (best friend); Shelly Winslow; Martin Petit; hundreds of the city''s poor, above all in Eastruins, who would shelter him and his staff and who pass on reliable tips', 'Supernatural evil: vampires, demons, Necromancers and other dark sorcerers', 'A detective known by one name, three years in Old Bones, who favours cases touching magic and the supernatural. Long black hair, usually tied back. The street guesses Mystic, Shifter, disguised dragon, Cyber-Knight or Tolkeen agent; none is right.', 'Rifts World Book 22: Free Quebec p.161'),
('syd-lycrean', 'Syd Lycrean', NULL, 'Owner of the Shade of Atlantis magic shop, Trade Center, Old Bones', 'rifts', NULL, '9th level Bio-Wizard', 9, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Mick Kilaan; Kyrforge; Murvoma Metzla (said to guard the shop by night)', NULL, 'Runs a three-story pyramid shop on a ley line whose dimensional gateway opens on Splynn, the source of a third of its stock. He lives at the top with two partners and collects intelligence on humans, the Coalition, Old Bones and Free Quebec, to what end nobody knows. Given as street rumor, which the book then confirms.', 'Rifts World Book 22: Free Quebec p.161'),
('mick-kilaan', 'Mick Kilaan', NULL, 'Partner in the Shade of Atlantis magic shop, Trade Center, Old Bones', 'rifts', NULL, '7th level Stone Mage', 7, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Syd Lycrean; Kyrforge', NULL, 'A seldom-seen partner in the Splynn-linked magic shop, living above it and sharing in its information gathering. Given as street rumor, which the book then confirms.', 'Rifts World Book 22: Free Quebec p.161'),
('kyrforge', 'Kyrforge', NULL, 'Partner in the Shade of Atlantis magic shop, Trade Center, Old Bones', 'rifts', NULL, '8th level Splugorth Conservator', 8, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Syd Lycrean; Mick Kilaan', NULL, 'A seldom-seen partner in the Splynn-linked magic shop who never appears without heavy hooded robes. Lives above the shop and shares in its information gathering. Given as street rumor, which the book then confirms.', 'Rifts World Book 22: Free Quebec p.161'),
('michael-barrett', 'Capt. Michael Barrett', NULL, 'Retired pirate and privateer captain of the lower St. Lawrence', 'rifts', NULL, 'Equivalent of a 9th level Privateer', 9, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Bionic replacement legs, both, below the knee', NULL, NULL, 'Has always worked both sides and would sign with the Coalition as readily as with Quebec, whichever makes the better case; pay is not the only thing that sways him. Reluctant to see battle again.', NULL, NULL, 'For years he raided Quebec freighters one week and escorted them the next, and many river pirates still take their cue from him. He gave up the sea about five years ago after losing both legs on his final voyage and lives hidden in the Prince Edward Islands. He would need a patrol or two to recover his edge. The class is in Coalition Navy p.117.', 'Rifts World Book 22: Free Quebec p.179');

-- Read the result back. This script asserts its OWN rows and nothing else.
SELECT 'all 12 notable NPCs are in' AS assertion, count(*) AS got, 12 AS want
  FROM notable_npcs WHERE slug IN ('pierre-champlain', 'sylvette-jiroyan', 'roland-desjardin', 'cyrean-hoist', 'shelly-winslow', 'martin-petit', 'philip-dushane', 'salmand', 'syd-lycrean', 'mick-kilaan', 'kyrforge', 'michael-barrett');
SELECT 'and the notables 0' AS assertion, count(*) AS got, 0 AS want
  FROM stat_attacks WHERE owner_kind = 'notable_npc' AND owner_slug IN ('pierre-champlain', 'sylvette-jiroyan', 'roland-desjardin', 'cyrean-hoist', 'shelly-winslow', 'martin-petit', 'philip-dushane', 'salmand', 'syd-lycrean', 'mick-kilaan', 'kyrforge', 'michael-barrett');

